    def is_first_last_digit_odd(n):
        first_digit = int(str(abs(n))[0])
        last_digit = int(str(abs(n))[-1])
        return first_digit % 2 == 1 and last_digit % 2 == 1

    count = 0
    for num in nums:
        if num > 10 and is_first_last_digit_odd(num):
            count += 1
    return count

