def cycpattern_check(a, b):
    """Check if the second word or any of its rotations is a substring in the first word."""
    # Check if b is a substring of a
    if b in a:
        return True

    # Check all rotations of b
    for i in range(len(b)):
        rotated = b[i:] + b[:i]
        if rotated in a:
            return True

    return False

