def prime_fib(n: int):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def is_fibonacci(num):
        a, b = 0, 1
        while b <= num:
            if b == num:
                return True
            a, b = b, a + b
        return False

    fib_numbers = []
    a, b = 0, 1
    while len(fib_numbers) < n:
        if is_prime(a) and is_fibonacci(a):
            fib_numbers.append(a)
        a, b = b, a + b

    return fib_numbers[-1]
